cat <<'EOF' > app/javascript/helpers/date_helpers.js
const MS_PER_DAY = 1000 * 60 * 60 * 24
const DATE_ONLY_PATTERN = /^\d{4}-\d{2}-\d{2}$/

export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / MS_PER_DAY)
}

export function beginningOfDay(date) {
  return new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()))
}

export function parseTimestamp(value) {
  if (!value) return null

  if (DATE_ONLY_PATTERN.test(value)) {
    const [ year, month, day ] = value.split("-").map(Number)
    return new Date(year, month - 1, day)
  }

  const date = new Date(value)
  return Number.isNaN(date.getTime()) ? null : date
}

export function formatLocalTime(date, style = "relative", now = new Date()) {
  const days = signedDifferenceInDays(now, date)

  switch (style) {
    case "time":
      return formatTime(date)
    case "date":
      return formatDateWithYear(date)
    case "shortdate":
      return formatContextualDate(date, now)
    case "datetime":
      return formatDateTime(date)
    case "weekday":
      return formatWeekday(date, now, days)
    case "indays":
      return formatInDays(days)
    case "ago":
      return formatAgo(date, now, days)
    case "relative":
    default:
      return formatRelative(date, now, days)
  }
}

export function formatFullTimestamp(date, rawValue = "") {
  if (DATE_ONLY_PATTERN.test(rawValue)) {
    return normalizeSpaces(formatters().fullDate.format(date))
  } else {
    return normalizeSpaces(formatters().fullDateTime.format(date))
  }
}

function formatRelative(date, now, days) {
  if (days === 0) {
    return formatTime(date)
  } else if (days === -1) {
    return "yesterday"
  } else if (days >= -6 && days <= -2) {
    return formatters().relative.format(days, "day")
  } else if (days === 1) {
    return "tomorrow"
  } else if (days >= 2) {
    return formatters().relative.format(days, "day")
  } else {
    return formatContextualDate(date, now)
  }
}

function formatAgo(date, now, days) {
  if (days === 0 || (days > 0 && date - now < 60_000)) {
    const seconds = Math.max(0, Math.floor((now - date) / 1000))

    if (seconds < 60) {
      return "just now"
    } else if (seconds < 3600) {
      return formatters().relative.format(-Math.floor(seconds / 60), "minute")
    } else {
      return formatters().relative.format(-Math.floor(seconds / 3600), "hour")
    }
  } else if (days === -1) {
    return "yesterday"
  } else if (days >= -6 && days <= -2) {
    return formatters().relative.format(days, "day")
  } else if (days === 1) {
    return "tomorrow"
  } else if (days >= 2) {
    return formatters().relative.format(days, "day")
  } else {
    return formatContextualDate(date, now)
  }
}

function formatInDays(days) {
  if (days <= 0) {
    return "today"
  } else if (days === 1) {
    return "tomorrow"
  } else {
    return formatters().relative.format(days, "day")
  }
}

function formatWeekday(date, now, days) {
  if (days === 0) {
    return "today"
  } else if (days === -1) {
    return "yesterday"
  } else if (days === 1) {
    return "tomorrow"
  } else if (date.getFullYear() === now.getFullYear()) {
    return normalizeSpaces(formatters().weekday.format(date))
  } else {
    return normalizeSpaces(formatters().weekdayWithYear.format(date))
  }
}

function formatContextualDate(date, now) {
  if (date.getFullYear() === now.getFullYear()) {
    return normalizeSpaces(formatters().shortDate.format(date))
  } else {
    return normalizeSpaces(formatters().dateWithYear.format(date))
  }
}

function formatTime(date) {
  return normalizeSpaces(formatters().time.format(date))
}

function formatDateWithYear(date) {
  return normalizeSpaces(formatters().dateWithYear.format(date))
}

function formatDateTime(date) {
  return normalizeSpaces(formatters().dateTime.format(date))
}

function normalizeSpaces(text) {
  return text.replace(/\s+/g, " ").trim()
}

let formatterCache = null
let formatterTimeZone = null

function formatters() {
  const timeZone = Intl.DateTimeFormat().resolvedOptions().timeZone

  if (!formatterCache || formatterTimeZone !== timeZone) {
    formatterTimeZone = timeZone
    formatterCache = {
      time: new Intl.DateTimeFormat("en-US", { timeZone, hour: "numeric", minute: "2-digit" }),
      shortDate: new Intl.DateTimeFormat("en-US", { timeZone, month: "short", day: "numeric" }),
      dateWithYear: new Intl.DateTimeFormat("en-US", { timeZone, month: "short", day: "numeric", year: "numeric" }),
      dateTime: new Intl.DateTimeFormat("en-US", { timeZone, month: "short", day: "numeric", year: "numeric", hour: "numeric", minute: "2-digit" }),
      weekday: new Intl.DateTimeFormat("en-US", { timeZone, weekday: "long", month: "long", day: "numeric" }),
      weekdayWithYear: new Intl.DateTimeFormat("en-US", { timeZone, weekday: "long", month: "long", day: "numeric", year: "numeric" }),
      fullDate: new Intl.DateTimeFormat("en-US", { timeZone, dateStyle: "long" }),
      fullDateTime: new Intl.DateTimeFormat("en-US", { timeZone, dateStyle: "long", timeStyle: "short" }),
      relative: new Intl.RelativeTimeFormat("en-US", { numeric: "auto" })
    }
  }

  return formatterCache
}
